-- Guards disabled CDN during backend updates and after failed recovery until a later successful update. No business rows are changed.
CREATE TRIGGER system.cdn_bootstrap_upstream_accounts_insert BEFORE INSERT ON system.cdnsell_upstream_accounts FOR EACH ROW BEGIN IF (SELECT enabled FROM system.cdnsell_settings WHERE id=1)=0 AND (EXISTS(SELECT 1 FROM system.update_tasks WHERE target='backend' AND status='running') OR COALESCE((SELECT status FROM system.update_tasks WHERE target='backend' ORDER BY created_at DESC,id DESC LIMIT 1),'')='failed') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CDN first update in progress'; END IF; END;
