CREATE TRIGGER system.cdn_bootstrap_settings_update BEFORE UPDATE ON system.cdnsell_settings FOR EACH ROW BEGIN IF NOT(NEW.enabled <=> OLD.enabled) AND (EXISTS(SELECT 1 FROM system.update_tasks WHERE target='backend' AND status='running') OR COALESCE((SELECT status FROM system.update_tasks WHERE target='backend' ORDER BY created_at DESC,id DESC LIMIT 1),'')='failed') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CDN switch locked during update'; END IF; END;
